class Knapsack
  private attr_reader :max_weight

  def initialize(max_weight)
    @max_weight = max_weight
  end

  def max_value(items)
    item_combinations = (1..items.length).flat_map { |n| items.combination(n).to_a }

    item_combinations
      .reject { _1.sum(&:weight) > max_weight }
      .map { _1.sum(&:value) }
      .max || 0
  end
